import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"What Orbit is","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),s={name:"guide/index.md"};function i(n,e,h,l,u,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-orbit-is" tabindex="-1">What Orbit is <a class="header-anchor" href="#what-orbit-is" aria-label="Permalink to &quot;What Orbit is&quot;">​</a></h1><p>Orbit is a platform you install on your own servers. It turns a fresh Linux machine into a place to run applications and databases, and gives you a console to do it without writing Kubernetes manifests or shell scripts.</p><h2 id="what-runs-where" tabindex="-1">What runs where <a class="header-anchor" href="#what-runs-where" aria-label="Permalink to &quot;What runs where {#what-runs-where}&quot;">​</a></h2><ul><li><strong>The main server:</strong> where you run the installer. It holds Orbit&#39;s control plane (the API, the console and its own database), Kubernetes (<a href="https://k3s.io" target="_blank" rel="noreferrer">K3s</a>), the Traefik router that receives your traffic, cert-manager for Let&#39;s Encrypt certificates, and BuildKit, which builds your repositories.</li><li><strong>More servers:</strong> you can add servers from the console. They join the same cluster and run the services you place on them.</li><li><strong>Your applications and databases:</strong> they run as Kubernetes workloads. They keep serving traffic while Orbit itself restarts or updates.</li></ul><h2 id="how-orbit-works-with-you" tabindex="-1">How Orbit works with you <a class="header-anchor" href="#how-orbit-works-with-you" aria-label="Permalink to &quot;How Orbit works with you {#how-orbit-works-with-you}&quot;">​</a></h2><ul><li><strong>Every change is an operation.</strong> Deploying, restoring, resizing or updating runs as an operation with steps, a log and a clear result. If Orbit restarts in the middle, the operation resumes or fails with the reason.</li><li><strong>Previews before changes.</strong> Changing resources, replicas or a database&#39;s runtime first shows what it reserves on each server, how it rolls out and what to watch out for. A change that does not fit is blocked.</li><li><strong>What you see is what was observed.</strong> Statuses come from the servers&#39; agents and Kubernetes. When Orbit has not heard from a server for a while, it says so instead of showing an old status.</li><li><strong>Limits are stated.</strong> Each screen says what a feature does not cover. <a href="./limits">What Orbit does not promise</a> lists them in one place.</li></ul><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start {#where-to-start}&quot;">​</a></h2><ol><li><a href="./install">Install Orbit</a> on a server.</li><li>Create a <a href="./projects">project</a> and deploy an <a href="./applications">application</a> from <a href="./github">GitHub</a>, <a href="./gitlab">GitLab</a>, <a href="./bitbucket">Bitbucket</a> or an image.</li><li>Add a <a href="./databases">database</a> and set its <a href="./backups">backups</a>.</li><li>Read <a href="./operating">Running Orbit</a> and <a href="./updates">Updates</a> before you depend on it.</li></ol><h2 id="console-appearance" tabindex="-1">Console appearance <a class="header-anchor" href="#console-appearance" aria-label="Permalink to &quot;Console appearance {#console-appearance}&quot;">​</a></h2><p>Open <strong>Settings &gt; General &gt; Appearance</strong>. Pick one of the themes or make your own from three colors, then pick <strong>Light</strong>, <strong>Dark</strong> or <strong>System</strong>. System follows your device throughout the day. Orbit saves your choices to your account so they follow you when you sign in on another device. <a href="./themes">Themes</a> covers making, tuning and sharing a theme, and giving one to a whole workspace.</p>',10)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
